'use strict';
const { app, BrowserWindow, webContents } = require('electron');
const assert = require('node:assert/strict');
const { mkdtemp, writeFile, rm, symlink } = require('node:fs/promises');
const { tmpdir } = require('node:os');
const { join } = require('node:path');
const { GuestAutomation } = require('../../browser-automation.cjs');
const { startFixture } = require('./browser-automation-fixture.cjs');
app.commandLine.appendSwitch('site-per-process');
app.commandLine.appendSwitch('disable-backgrounding-occluded-windows');
app.commandLine.appendSwitch('disable-renderer-backgrounding');
let sequence = 0;
app.whenReady().then(async () => {
  const directory = await mkdtemp(join(tmpdir(), 'nm-browser-acceptance-'));
  let fixture, window, engine;
  try {
    fixture = await startFixture();
    window = new BrowserWindow({ show: false, width: 1100, height: 900, webPreferences: { sandbox: false, nodeIntegration: true, contextIsolation: false, webviewTag: true } });
    const guestCreated = new Promise(resolve => window.webContents.once('did-attach-webview', (_event, guest) => resolve(guest)));
    await window.loadURL(`data:text/html,${encodeURIComponent(`<webview src="${fixture.url}" style="width:100%;height:850px" partition="persist:nextmux-browser"></webview>`)}`);
    const contents = await guestCreated;
    if (contents.isLoading()) await new Promise(resolve => contents.once('did-stop-loading', resolve));
    assert.equal(contents.getType(), 'webview');
    const originalThrottling = contents.getBackgroundThrottling();
    engine = await GuestAutomation.create(contents);
    const run = async values => {
      const result = await engine.run({ id: `fixture-${++sequence}`, conversationId: 'fixture-conversation', browserId: 'fixture-browser', workspaceRoot: directory, expiresAt: Date.now() + 15_000, ...values });
      console.log(JSON.stringify({ action: values.action, selector: values.selector, ok: result.ok, message: result.message }));
      assert.equal(contents.getBackgroundThrottling(), originalThrottling, 'idle background throttling must be restored');
      return result;
    };
    let shot = (await run({ action: 'snapshot' })).data;
    assert.equal(shot.frames.length, 2);
    assert.ok(engine.transport.sessions.size > 0, 'iframe must be an actual out-of-process child CDP session');
    let child = shot.elements.find(element => element.name === 'Frame action');
    assert.ok(child);
    assert.equal((await run({ action: 'click', ref: child.ref })).ok, true);
    assert.equal(await engine.page.frames().find(frame => frame !== engine.page.mainFrame()).$eval('#frame-result', el => el.textContent), 'frame clicked');
    await contents.executeJavaScript(`const cover = document.createElement('div'); cover.id='frame-cover'; const bounds=document.querySelector('iframe').getBoundingClientRect(); Object.assign(cover.style,{position:'fixed',left:bounds.x+'px',top:bounds.y+'px',width:bounds.width+'px',height:bounds.height+'px',background:'gray',zIndex:1000});document.body.append(cover);`);
    shot = (await run({ action: 'snapshot' })).data;
    child = shot.elements.find(element => element.name === 'Frame action');
    assert.equal((await run({ action: 'click', ref: child.ref, timeoutMs: 200 })).ok, false);
    await contents.executeJavaScript('document.querySelector("#frame-cover").remove()');
    assert.match(await contents.executeJavaScript('document.body.innerText'), /Run action/);
    assert.equal((await run({ action: 'click', selector: '#click' })).ok, true);
    assert.equal(await contents.executeJavaScript('document.querySelector("#result").textContent'), 'clicked');
    await window.webContents.executeJavaScript('Object.assign(document.querySelector("webview").style,{position:"fixed",left:"-10000px",top:"0",width:"1024px",height:"768px",opacity:"0",pointerEvents:"none"});document.querySelector("webview").inert=true');
    await contents.executeJavaScript('document.querySelector("#result").textContent="background waiting"');
    assert.equal((await run({ action: 'click', selector: '#click', timeoutMs: 2000 })).ok, true);
    assert.equal(await contents.executeJavaScript('document.querySelector("#result").textContent'), 'clicked');
    await window.webContents.executeJavaScript('document.querySelector("webview").style="width:100%;height:850px";document.querySelector("webview").inert=false');
    assert.ok(await window.webContents.executeJavaScript('document.querySelector("webview").getBoundingClientRect().x >= 0'), 'returning to foreground must restore normal layout');
    const filled = await run({ action: 'fill', selector: '#name', text: 'NextMux' });
    assert.equal(filled.ok, true);
    assert.equal(filled.data.snapshot.elements.find(element => element.name === 'Name').value, 'NextMux');
    assert.equal(await contents.executeJavaScript('document.querySelector("#name").value'), 'NextMux');
    const selected = await run({ action: 'select', selector: '#choice', values: ['blue'] });
    assert.equal(selected.ok, true);
    assert.deepEqual(selected.data.snapshot.elements.find(element => element.name === 'Colour').selectedValues, ['blue']);
    assert.equal(await contents.executeJavaScript('document.querySelector("#choice").value'), 'blue');
    const upload = join(directory, 'fixture.txt'); await writeFile(upload, 'acceptance');
    assert.equal((await run({ action: 'upload', selector: '#file', paths: [upload] })).ok, true);
    assert.equal(await contents.executeJavaScript('document.querySelector("#file").files[0].name'), 'fixture.txt');
    shot = (await run({ action: 'snapshot' })).data;
    const hiddenFile = shot.elements.find(element => element.name === 'Hidden upload');
    assert.equal(hiddenFile?.inputType, 'file');
    assert.equal((await run({ action: 'upload', ref: hiddenFile.ref, paths: [upload] })).ok, true);
    assert.equal(await contents.executeJavaScript('document.querySelector("#hidden-file").files[0].name'), 'fixture.txt');
    assert.equal((await run({ action: 'upload', selector: '#file', paths: [__filename] })).ok, false);
    await symlink(__filename, join(directory, 'outside.txt'));
    assert.equal((await run({ action: 'upload', selector: '#file', paths: [join(directory, 'outside.txt')] })).ok, false);
    shot = (await run({ action: 'snapshot' })).data;
    const dragSource = shot.elements.find(element => element.name === 'Drag source');
    const dropTarget = shot.elements.find(element => element.name === 'Drop destination');
    assert.equal(dropTarget?.dropTarget, true);
    const dragged = await run({ action: 'drag', ref: dragSource.ref, targetRef: dropTarget.ref });
    assert.equal(dragged.ok, true);
    assert.ok(dragged.data.snapshot.elements.find(element => element.name === 'nextmux-fixture' && element.dropTarget));
    assert.equal(await contents.executeJavaScript('document.querySelector("#destination").textContent'), 'nextmux-fixture');
    setTimeout(() => void contents.executeJavaScript('document.querySelector("#later").disabled=false'), 250);
    assert.equal((await run({ action: 'click', selector: '#later' })).ok, true);
    assert.equal((await run({ action: 'click', selector: '#covered', timeoutMs: 200 })).ok, false);
    const pending = engine.run({ id: 'cancel-operation', action: 'click', selector: '#never', expiresAt: Date.now() + 10_000 });
    setTimeout(() => engine.cancel('cancel-operation'), 100);
    assert.equal((await pending).ok, false);
    await contents.executeJavaScript('document.querySelector("#never").disabled=false');
    assert.equal(await contents.executeJavaScript('document.querySelector("#never").textContent'), 'Cancelled action');
    shot = (await run({ action: 'snapshot' })).data;
    const old = shot.elements[0].ref;
    await run({ action: 'snapshot' });
    assert.equal((await run({ action: 'click', ref: old })).ok, false);
    await assert.rejects(engine.transport.dispatch({ method: 'Target.createTarget', params: { url: 'about:blank' } }), /not allowed/);
    await assert.rejects(engine.transport.dispatch({ method: 'Runtime.evaluate', sessionId: 'another-tab', params: {} }), /Foreign/);
    assert.equal(webContents.getAllWebContents().filter(item => item.getType() === 'webview').length, 1);
    console.log('NATIVE_BROWSER_ACCEPTANCE_PASSED');
  } catch (error) { console.error(error); process.exitCode = 1; }
  finally {
    await engine?.dispose(); window?.destroy(); await fixture?.close(); await rm(directory, { recursive: true, force: true }); app.exit(process.exitCode || 0);
  }
});
